!function(){"use strict";const a={paithan:{title:"Pratishthana (Paithan Capital)",sub:"Primary Imperial Mint & Administrative Seat (c. 1st Century BCE – 2nd Century CE)",desc:"Located on the upper Godavari River in Maharashtra, Paithan served as the primary capital of the Satavahana rulers. Excavations yielded numerous potin and lead coins bearing the Ujjain emblem and royal legends of Simuka, Satakarni I, and Pulumavi.",ruler:"Simuka, Satakarni I & Gautamiputra Satakarni",types:"Potin Elephant, Ujjain Cross, Hill/Stupa Motifs",metals:"Potin, Lead, Copper"},amaravati:{title:"Amaravati / Dharanikota (Eastern Capital)",sub:"Maritime Hub & Stupa Patronage Site (Andhra Pradesh)",desc:"Dharanikota (near Amaravati on the lower Krishna River) was the eastern seat of power. It produced the iconic two-masted ship coins of Yajna Sri Satakarni, marking thriving maritime commerce with Rome, Ceylon, and Southeast Asia.",ruler:"Vashishtiputra Pulumavi & Yajna Sri Satakarni",types:"Two-Masted Ship Coins, Bilingual Silver Dinaras",metals:"Silver, Lead, Bronze"},nevasa:{title:"Nevasa Excavations & Hoard Site",sub:"Major Archaeological Discovery Center (Ahmadnagar District)",desc:"Scientific excavations at Nevasa uncovered stratified coin layers showing the chronological transition of Satavahana coin metallurgy from early cast copper coins to die-struck lead and potin issues.",ruler:"Satakarni II & Gautamiputra Satakarni",types:"Three-Arched Hill with Crescent, Bull Motifs",metals:"Lead & Potin Alloys"},kotalingala:{title:"Kotalingala Archaeological Site",sub:"Earliest Dynastic Mint Site (Karimnagar District, Telangana)",desc:"Discoveries at Kotalingala revealed rare early coins inscribed with 'Rano Siri Chimuka Satavahanasa' (King Simuka Satavahana), establishing the origin of the dynasty in Telangana before expansion across the Deccan.",ruler:"Simuka (Founder), Kanha, Satakarni I",types:"Early Inscribed Copper & Potin Issues",metals:"Copper, Potin"},junnar:{title:"Junnar Rock-Cut Pass & Mint Hub",sub:"Western Ghats Trade Pass (Pune District, Maharashtra)",desc:"Commanding the Naneghat trade pass connecting the Deccan plateau with the Arabian Sea coast. Junnar issued distinct coin types featuring standing lions, humped bulls, and sacred trees inside railings.",ruler:"Hala, Gautamiputra Satakarni",types:"Lion-Type Coppers, Sacred Tree in Railing",metals:"Copper, Potin"}},e=[{id:"ship-lead",name:"Yajna Sri Satakarni Ship Lead Coin",ruler:"Yajna Sri Satakarni (c. 167–196 CE)",metal:"Lead",symbol:"Twin-masted ship with rigging",script:"Brahmi script reading 'Siri Yajna Satakanisa'",region:"Amaravati / Coastal Andhra",desc:"Celebrated maritime coin featuring a detailed 2-masted sea vessel with rigging and oars."},{id:"silver-gautamiputra",name:"Gautamiputra Silver Drachm (Restruck)",ruler:"Gautamiputra Satakarni (c. 106–130 CE)",metal:"Silver",symbol:"Three-arched hill (Ujjain reverse)",script:"Brahmi / Southern Proto-Telugu",region:"Jogalthambi Hoard / Nashik",desc:"Famous silver coin restruck over Western Kshatrapa (Nahapana) drachms following Gautamiputra's victory."},{id:"potin-elephant",name:"Satakarni I Potin Elephant Coin",ruler:"Satakarni I (c. 70–60 BCE)",metal:"Potin (Copper-Tin Alloy)",symbol:"Upright Elephant with raised trunk",script:"Early Brahmi script",region:"Paithan / Malwa",desc:"Heavy potin coin featuring royal elephant on obverse and Ujjain cross emblem on reverse."},{id:"lion-junnar",name:"Junnar Solar Lion Copper Coin",ruler:"King Hala / Gautamiputra",metal:"Copper",symbol:"Solar Lion standing right",script:"Prakrit in Brahmi",region:"Junnar / Western Ghats",desc:"Regional coin issue minted for trade along the Naneghat mountain pass."}],t=[{ruler:"Simuka (Founder)",period:"c. 120 – 90 BCE",desc:"Established Satavahana power in Central Deccan (Kotalingala); issued early inscribed copper Karshapanas."},{ruler:"Satakarni I",period:"c. 70 – 60 BCE",desc:"Expanded territory into Malwa and Narmada valley; performed Ashvamedha sacrifice recorded in Naneghat inscription; issued potin elephant coins."},{ruler:"Gautamiputra Satakarni",period:"c. 106 – 130 CE",desc:"Destroyed the Kshaharata Kshatrapa dynasty (Nahapana); restruck thousands of silver coins; consolidated Deccan from sea to sea."},{ruler:"Vashishtiputra Pulumavi",period:"c. 130 – 159 CE",desc:"Expanded capital to Pratishthana; embellished Amaravati Great Stupa; issued bilingual silver portrait coins."},{ruler:"Yajna Sri Satakarni",period:"c. 167 – 196 CE",desc:"Re-established control over coastal trade routes; famous for issuing ocean-going ship coins."}];document.addEventListener("DOMContentLoaded",function(){const n=document.querySelectorAll(".deccan-hotspot"),i=document.getElementById("site-title"),r=document.getElementById("site-sub"),s=document.getElementById("site-body"),o=document.getElementById("detail-ruler"),l=document.getElementById("detail-types"),c=document.getElementById("detail-metals"),d=document.getElementById("sat-coin-1"),m=document.getElementById("sat-coin-2"),u=document.getElementById("sat-compare-grid"),p=document.getElementById("sat-timeline"),h=document.getElementById("theme-toggle");function g(){if(!u)return;const a=e[d.value],t=e[m.value];u.innerHTML=`\n        <div class="compare-sat-card">\n          <h4 style="color: var(--sat-gold); font-size: 1.2rem; margin-bottom: 6px;">${a.name}</h4>\n          <span style="font-size: 0.85rem; color: var(--text-secondary); display: block; margin-bottom: 14px;">${a.ruler}</span>\n          <p style="font-size: 0.9rem; color: var(--text-primary); margin-bottom: 16px;">${a.desc}</p>\n          <ul style="list-style: none; padding: 0; font-size: 0.85rem; color: var(--text-secondary);">\n            <li style="margin-bottom: 6px;"><strong>Metal:</strong> ${a.metal}</li>\n            <li style="margin-bottom: 6px;"><strong>Symbol:</strong> ${a.symbol}</li>\n            <li style="margin-bottom: 6px;"><strong>Inscriptions:</strong> ${a.script}</li>\n            <li style="margin-bottom: 6px;"><strong>Circulation:</strong> ${a.region}</li>\n          </ul>\n        </div>\n\n        <div class="compare-sat-card">\n          <h4 style="color: var(--sat-gold); font-size: 1.2rem; margin-bottom: 6px;">${t.name}</h4>\n          <span style="font-size: 0.85rem; color: var(--text-secondary); display: block; margin-bottom: 14px;">${t.ruler}</span>\n          <p style="font-size: 0.9rem; color: var(--text-primary); margin-bottom: 16px;">${t.desc}</p>\n          <ul style="list-style: none; padding: 0; font-size: 0.85rem; color: var(--text-secondary);">\n            <li style="margin-bottom: 6px;"><strong>Metal:</strong> ${t.metal}</li>\n            <li style="margin-bottom: 6px;"><strong>Symbol:</strong> ${t.symbol}</li>\n            <li style="margin-bottom: 6px;"><strong>Inscriptions:</strong> ${t.script}</li>\n            <li style="margin-bottom: 6px;"><strong>Circulation:</strong> ${t.region}</li>\n          </ul>\n        </div>\n      `}h&&h.addEventListener("click",function(){document.body.classList.toggle("light-theme");const a=document.body.classList.contains("light-theme");localStorage.setItem("theme",a?"light":"dark")}),n.forEach(function(e){e.addEventListener("click",function(){const t=e.getAttribute("data-site"),n=a[t];n&&(i&&(i.textContent=n.title),r&&(r.textContent=n.sub),s&&(s.innerHTML=`<p>${n.desc}</p>`),o&&(o.textContent=n.ruler),l&&(l.textContent=n.types),c&&(c.textContent=n.metals))})});const y=document.getElementById("menu-toggle"),v=document.getElementById("nav-menu");y&&v&&y.addEventListener("click",()=>v.classList.toggle("active")),d&&m&&(d.innerHTML="",m.innerHTML="",e.forEach((a,e)=>{d.add(new Option(a.name,e)),m.add(new Option(a.name,e))}),d.value=0,m.value=1,d.addEventListener("change",g),m.addEventListener("change",g),g()),p&&(p.innerHTML="",t.forEach(a=>{const e=document.createElement("div");e.className="timeline-item",e.innerHTML=`\n          <h4>${a.ruler}</h4>\n          <span class="timeline-date">${a.period}</span>\n          <p>${a.desc}</p>\n        `,p.appendChild(e)}))})}();